; seek_u8_u8_dda: exact "move object toward target" (bulk Bresenham DDA)
;
; GENERATED by tools/generate_seek_sources.py from tools/seek_kernel.py; the
; C64 Math Library installs the same kernel as MATH_SEEK8_*.
;
; x and y are unsigned bytes (0..255; use x/2 for full-width sprite X).
;
; Speed: MATH-style Q8.8 pixels per frame. SPL = fraction, SPH bits 0-6 =
; integer part (0..126). SPH bit 7 selects the speed meaning:
;   0  speed along the MAJOR axis (classic Bresenham: a 45 degree move covers
;      sqrt(2) x the distance per frame)
;   1  speed along the path (constant Euclidean speed, within 0.7%)
;
; Every frame's position is on the Bresenham line from the start to the target
; (within 0.5 px of the true line) and the object lands exactly on the target.
; Each frame moves the major axis by k = floor or ceil of the speed and the
; minor axis by the exact Bresenham amount for k pixels, precomputed at init as
; k*dmin = whole_k*dmaj + rem_k. One counter R = dmaj*256 - 1 - speeds so far
; carries both the speed fraction (borrow out of its low byte: this frame moves
; k0+1) and the distance (borrow out of the top: arrival).
;
; X = slot (0..7) for every entry and is preserved; A/Y are volatile; D=0 is
; required. The start position is whatever POS_* holds for the slot. The
; steppers return C=1 on the frame the target is reached and on every later
; call (the position stays on the target), else C=0; they use no scratch.
; Init returns C=1 if the object is already on the target, else C=0.
; Use one stepper per move: STEP (any speed), STEP_INT (major-axis integer
; speed >= 1 with bit 7 clear; ignores the fraction) or STEP1 (init with speed
; $0100; exactly 1 px/frame; uses NMOS DCP).
;
; Entries: seek8_init, seek8_step, seek8_step_int, seek8_step1.
;
; Inputs (IO block): IN_X = target x, IN_Y = target y,
; IN_SPL/IN_SPH = speed. Inputs are preserved.
;
; Configure before assembly:
;   ORG  code origin
;   IO   24 bytes: inputs at +0..+4, init scratch at +5.. (zero page
;        recommended)
;   ST   160 bytes of per-slot state, 8-byte aligned (NSLOT = 8)
; The object position is S8_POS_X, S8_POS_Y+slot.
!cpu 6510
ORG = $8000
IO  = $E0
ST  = $9000

SEEK_IN_X   = IO+0
SEEK_IN_XH  = IO+1
SEEK_IN_Y   = IO+2
SEEK_IN_SPL = IO+3
SEEK_IN_SPH = IO+4
SEEK_T      = IO+5
SK_EMAJ   = SEEK_T+0
SK_EMIN   = SEEK_T+1
SK_Q      = SEEK_T+2
SK_PH     = SEEK_T+3
SK_SPH    = SEEK_T+4
SK_MX     = SEEK_T+5
SK_MY     = SEEK_T+6
SK_MODE   = SEEK_T+7
SK_WHOLE  = SEEK_T+8
SK_UN     = SEEK_T+9
SK_SGN    = SEEK_T+10
SK_VMAJ   = SEEK_T+11
SK_T      = SEEK_T+12
SK_DMAJL  = SEEK_T+13
SK_DMAJH  = SEEK_T+14
SK_DMIN   = SEEK_T+15
SK_REML   = SEEK_T+16
SK_REMH   = SEEK_T+17
SK_REM8   = SEEK_T+18

S8_POS_X   = ST+0
S8_POS_Y   = ST+8
S8_TGT_X   = ST+16
S8_TGT_Y   = ST+24
S8_RL      = ST+32
S8_RH      = ST+40
S8_ERR     = ST+48
S8_DMAJ    = ST+56
S8_KF      = ST+64
S8_KI      = ST+72
S8_REM     = ST+80
S8_VX      = ST+96
S8_VY      = ST+128

* = ORG

; ---- SEEK8 per-frame steppers ----
seek8_step:
        lda S8_RL,x             ; R -= speed; low borrow: this frame moves k0+1
        sec
        sbc S8_KF,x
        sta S8_RL,x
        bcc s8_set1
seek8_step_int:
        sec
        lda S8_RH,x             ; k0 frame (also the integer stepper)
        sbc S8_KI,x
        sta S8_RH,x
        bcc s8_arrive
s8_move0:
        lda S8_ERR,x            ; C=1: err -= rem_k
        sbc S8_REM,x
        bcc s8_wrap0
        sta S8_ERR,x
        lda S8_POS_X,x          ; C=1 into VX; VY absorbs the carry out
        adc S8_VX,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY,x
        sta S8_POS_Y,x
        clc
        rts
s8_wrap0:
        adc S8_DMAJ,x           ; err += dmaj; the true sum is >= 0, so C=1
        sta S8_ERR,x
        lda S8_POS_X,x
        adc S8_VX+16,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY+16,x
        sta S8_POS_Y,x
        clc
        rts
seek8_step1:
        lda #$FF                ; DCP: RH -= 1 and compare with $FF in one go.
        !byte $DF, <S8_RH, >S8_RH    ; DCP S8_RH,X
        bne s8_move0            ; Z=1 only when RH wrapped (arrival); C=1
s8_arrive:
        lda S8_TGT_X,x          ; land exactly on the target
        sta S8_POS_X,x
        lda S8_TGT_Y,x
        sta S8_POS_Y,x
s8_arrived:
        lda #0                  ; R = 0 and k0 = 1: every later call borrows
        sta S8_RH,x             ; out of RH and snaps again
        lda #1
        sta S8_KI,x
        sec
        rts
s8_set1:
        lda S8_RH,x             ; C=0: subtracts k0+1
        sbc S8_KI,x
        sta S8_RH,x
        bcc s8_arrive
        lda S8_ERR,x
        sbc S8_REM+8,x
        bcc s8_wrap1
        sta S8_ERR,x
        lda S8_POS_X,x
        adc S8_VX+8,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY+8,x
        sta S8_POS_Y,x
        clc
        rts
s8_wrap1:
        adc S8_DMAJ,x
        sta S8_ERR,x
        lda S8_POS_X,x
        adc S8_VX+24,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY+24,x
        sta S8_POS_Y,x
        clc
        rts

; ---- SEEK8 init ----
seek8_init:
        lda #$FF
        sta S8_RL,x
        ldy #0
        lda SEEK_IN_Y
        sta S8_TGT_Y,x
        sec
        sbc S8_POS_Y,x
        bcs s8i_dy
        eor #$FF
        adc #1                  ; C=0
        dey
s8i_dy:
        sta SK_EMIN
        sty SK_MY
        ldy #0
        lda SEEK_IN_X
        sta S8_TGT_X,x
        sec
        sbc S8_POS_X,x
        bcs s8i_dx
        eor #$FF
        adc #1
        dey
s8i_dx:
        sty SK_MX
        cmp SK_EMIN
        bcs s8i_xmaj
        ldy SK_EMIN             ; y major: dmaj = |dy|, dmin = |dx|
        sta SK_EMIN
        lda SK_MX
        ora #1
        sta SK_UN               ; minor unit = x direction
        tya
        ldy #$80
        bne s8i_mode
s8i_xmaj:
        tay
        lda SK_MY
        ora #1
        sta SK_UN               ; minor unit = y direction
        tya
        ldy #0
s8i_mode:
        sty SK_MODE
        sta SK_EMAJ
        sta S8_DMAJ,x
        lsr
        sta S8_ERR,x            ; err = dmaj/2
        lda SK_EMAJ
        sec
        sbc #1
        sta S8_RH,x             ; RH:RL = dmaj*256-1
        bcc s8i_zero
        lda SEEK_IN_SPH
        bmi s8i_euclid
        sta S8_KI,x
        lda SEEK_IN_SPL
        sta S8_KF,x
s8i_rates:
        lda #0                  ; rem0 = k0*dmin mod dmaj, whole0 = div
        sta SK_WHOLE
        ldy S8_KI,x
        beq s8i_r0done
s8i_r0:
        clc
        adc SK_EMIN
        bcs s8i_r0sub
        cmp SK_EMAJ
        bcc s8i_r0next
s8i_r0sub:
        sbc SK_EMAJ             ; C=1 on both paths
        inc SK_WHOLE
s8i_r0next:
        dey
        bne s8i_r0
s8i_r0done:
        sta S8_REM,x
        sta SK_REM8
        txa
        tay                     ; planes for k0 at Y = slot
        lda S8_KI,x
        jsr s8_planes
        lda S8_KF,x             ; integer speed: the k0+1 planes are never used
        beq s8i_done
        lda SK_REM8             ; rem1 = rem0 + dmin (at most one more wrap)
        clc
        adc SK_EMIN
        bcs s8i_r1sub
        cmp SK_EMAJ
        bcc s8i_r1done
s8i_r1sub:
        sbc SK_EMAJ
        inc SK_WHOLE
s8i_r1done:
        sta S8_REM+8,x
        txa
        ora #8                  ; Y = slot+8 (slot < 8)
        tay
        lda S8_KI,x
        sec
        adc #0                  ; k0+1
        jsr s8_planes
s8i_done:
        clc
        rts
s8i_zero:
        jmp s8_arrived          ; C=1
s8i_euclid:
        jsr seek_euclid_speed   ; A = integer, Y = fraction
        sta S8_KI,x
        tya
        sta S8_KF,x
        jmp s8i_rates

; ---- SEEK8 plane writer ----
; A = k, SK_WHOLE = whole, Y = plane index (slot or slot+8). Writes the
; no-wrap plane at Y and the wrap plane at Y+16.
; Stored values: VX = vx-1 (added with C=1) and VY = vy + sign(VX), which
; absorbs the carry out of the x add.
s8_planes:
        bit SK_MODE
        bmi s8p_ymaj
        eor SK_MX               ; x major: VX = (k eor m) - m - 1
        clc
        sbc SK_MX
        sta S8_VX,y
        sta S8_VX+16,y
        ora #$7F
        bmi s8p_xs
        lda #0
s8p_xs:
        sta SK_SGN
        lda SK_WHOLE            ; vy = (whole eor m) - m
        eor SK_MY
        sec
        sbc SK_MY
        clc
        adc SK_SGN
        sta S8_VY,y
        clc
        adc SK_UN               ; wrap: one more minor step
        sta S8_VY+16,y
        rts
s8p_ymaj:
        eor SK_MY               ; y major: vy = (k eor m) - m
        sec
        sbc SK_MY
        sta SK_VMAJ
        lda SK_WHOLE            ; VX = (whole eor m) - m - 1
        eor SK_MX
        clc
        sbc SK_MX
        sta S8_VX,y
        sta SK_T
        ora #$7F
        bmi s8p_y0
        lda #0
s8p_y0:
        clc
        adc SK_VMAJ
        sta S8_VY,y
        lda SK_T                ; wrap: VX + unit
        clc
        adc SK_UN
        sta S8_VX+16,y
        ora #$7F
        bmi s8p_y1
        lda #0
s8p_y1:
        clc
        adc SK_VMAJ
        sta S8_VY+16,y
        rts

; ---- shared: Euclidean speed -> major-axis speed ----
; In: SK_EMAJ >= 1 and SK_EMIN <= SK_EMAJ (8-bit magnitudes), speed in
; SEEK_IN_SPL/SEEK_IN_SPH (bit 7 ignored). Out: A = integer, Y = fraction of
; speed*cos(atan(dmin/dmaj)) = speed - (speed*d >> 8), d = seek_cos_d[q],
; q = min(31, floor(32*dmin/dmaj)). Preserves X.
seek_euclid_speed:
        lda SEEK_IN_SPH
        and #$7F
        sta SK_SPH
        lda #$08                ; quotient sentinel: 5 rols push it into C
        sta SK_Q
        lda SK_EMIN
seu_div:
        asl
        bcs seu_sub
        cmp SK_EMAJ
        bcc seu_skip
seu_sub:
        sbc SK_EMAJ
        sec
seu_skip:
        rol SK_Q
        bcc seu_div
        ldy SK_Q
        lda #0
        sta SK_PH
        lda seek_cos_d,y        ; d leaves LSB first; the sentinel in bit 7
        sec                     ; ends the loop after 8 shifts
        ror
        sta SK_Q
        lda #0
seu_mul:
        bcc seu_mskip
        clc
        adc SEEK_IN_SPL
        tay
        lda SK_PH
        adc SK_SPH
        sta SK_PH
        tya
seu_mskip:
        ror SK_PH
        ror
        lsr SK_Q
        bne seu_mul
        sta SK_Q                ; speed - P
        lda SEEK_IN_SPL
        sec
        sbc SK_Q
        tay
        lda SK_SPH
        sbc SK_PH
        rts

; cos_d[q] = round(256*(1-cos(atan((q+0.5)/32))))
seek_cos_d:
        !byte 0, 0, 1, 2, 2, 4, 5, 7
        !byte 9, 11, 13, 15, 18, 20, 23, 26
        !byte 28, 31, 34, 37, 40, 44, 47, 50
        !byte 53, 56, 59, 62, 65, 68, 71, 74
